protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Pin to old name so existing documents and direct SQL queries (c.Discriminator) still work.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed id format from "Product|123" to "123".
        // Keep the old compound format so existing 500K documents remain accessible.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // HasIndex removed — EF Core 9 Cosmos provider now throws on HasIndex.
    // Cosmos DB indexing is managed via the container's indexing policy (Azure Portal / Bicep).
}

